#include <stdio.h>
typedef struct Axis6W4ReplayRow { unsigned int lane, phase, watermark, token; int delta; } Axis6W4ReplayRow;
typedef struct Axis6W4ReplayAgg { unsigned int phase[4], watermark[4], seen_mask[4]; int value[4]; } Axis6W4ReplayAgg;
static unsigned int mix4r(unsigned int h,unsigned int v){ h ^= v + 0x9e3779b9u + (h<<6) + (h>>2); return h; }
static void clear4r(Axis6W4ReplayAgg* a){ for(int i=0;i<4;++i){ a->phase[i]=0u; a->watermark[i]=0u; a->seen_mask[i]=0u; a->value[i]=0; } }
static void absorb4r(Axis6W4ReplayAgg* a,const Axis6W4ReplayRow* r){ unsigned int lane=r->lane%4u; if(r->phase<a->phase[lane]) return; if(r->phase>a->phase[lane]){ a->phase[lane]=r->phase; a->watermark[lane]=r->watermark; a->seen_mask[lane]=1u<<(r->token&31u); a->value[lane]=r->delta; return;} if(r->watermark<a->watermark[lane]) return; if(r->watermark>a->watermark[lane]){ a->watermark[lane]=r->watermark; a->seen_mask[lane]=1u<<(r->token&31u); a->value[lane]=r->delta; return;} { unsigned int bit=1u<<(r->token&31u); if(a->seen_mask[lane]&bit) return; a->seen_mask[lane]|=bit; } a->value[lane]+=r->delta; }
static unsigned int sig4r(const Axis6W4ReplayAgg* a){ unsigned int h=2166136261u; for(unsigned int lane=0; lane<4u; ++lane){ h=mix4r(h,lane+1u); h=mix4r(h,a->phase[lane]); h=mix4r(h,a->watermark[lane]); h=mix4r(h,a->seen_mask[lane]); h=mix4r(h,(unsigned int)(a->value[lane]&0xffff)); } return h; }
static void batch4r(Axis6W4ReplayAgg* a,const Axis6W4ReplayRow* rows,unsigned int count){ for(unsigned int i=0;i<count;++i) absorb4r(a,&rows[i]); }
int main(void){ const Axis6W4ReplayRow canonical[]={{0u,4u,2u,11u,5},{0u,4u,2u,17u,-1},{1u,5u,3u,13u,4},{1u,5u,3u,19u,2},{2u,6u,4u,23u,7},{2u,6u,4u,29u,-3},{3u,4u,5u,31u,6},{3u,4u,5u,5u,1}}; const Axis6W4ReplayRow replay_a[]={{0u,2u,1u,3u,1},{0u,4u,2u,11u,5},{1u,3u,2u,7u,2},{2u,6u,4u,23u,7},{1u,5u,3u,13u,4},{0u,4u,2u,11u,5},{3u,4u,5u,31u,6},{2u,6u,4u,29u,-3},{1u,5u,3u,19u,2},{3u,4u,5u,31u,6},{0u,4u,2u,17u,-1},{3u,4u,5u,5u,1}}; const Axis6W4ReplayRow replay_b[]={{3u,1u,2u,9u,4},{3u,4u,5u,5u,1},{1u,5u,3u,19u,2},{0u,4u,2u,17u,-1},{2u,6u,4u,23u,7},{1u,5u,3u,13u,4},{0u,4u,2u,11u,5},{3u,4u,5u,31u,6},{2u,6u,4u,29u,-3},{0u,4u,2u,17u,-1},{1u,5u,3u,19u,2},{3u,4u,5u,5u,1}}; Axis6W4ReplayAgg d,a,b; clear4r(&d); batch4r(&d,canonical,sizeof(canonical)/sizeof(canonical[0])); clear4r(&a); batch4r(&a,replay_a,sizeof(replay_a)/sizeof(replay_a[0])); clear4r(&b); batch4r(&b,replay_b,sizeof(replay_b)/sizeof(replay_b[0])); unsigned int sd=sig4r(&d), sa=sig4r(&a), sb=sig4r(&b); printf("%u %u %u %u\n", sd, sa, sb, (sd==sa && sd==sb)?1u:0u); return 0; }
